test('dropping a task on a paper target inserts at that position and refuses duplicate families or foreign scopes',async()=>{const u=await ui('admin'),d=u.sandbox.testUI.getDb();const t=d.tasks[0],other=structuredClone(t);other.id='another-task';other.familyId='demo-family-2';other.planningCategories=['machinery'];other.planningCategoryCatalog='zp-general-2026';other.text='Aufgabe: Einsetzen von Maschinen und Geräten. Hier: Synthetischer Arbeitsauftrag.';d.tasks.push(other);const e=C.newExam({specialty:t.specialty,examType:t.examType,examYear:2027,workshopId:'meeting',pattern:L.pattern(d,t.examType,t.specialty)});C.addItem(e,t);d.exams.push(e);await u.click('action','select-exam',e.id);const drop=id=>u.dispatch('drop',{target:{closest:()=>({dataset:{paperBefore:e.items[0].id},classList:{remove(){}}})},preventDefault(){},dataTransfer:{getData:()=> 'task:'+id}});drop(other.id);assert.deepEqual(e.items.map(i=>i.originTaskId),[other.id,t.id]);drop(t.id);assert.equal(e.items.length,2);drop('demo-task-2');assert.equal(e.items.length,2);});
test('groups cannot use the coordinator cleanup actions for drafts',async()=>{const u=await ui(),d=u.sandbox.testUI.getDb(),t=d.tasks.find(t=>t.specialty==='Baumschule'&&t.examType==='ZP'),e=C.newExam({specialty:t.specialty,examType:t.examType,examYear:2027,workshopId:'meeting',pattern:L.pattern(d,t.examType,t.specialty)}),gone=C.newExam();C.trashExam({exams:[gone],uses:[]},gone.id);d.exams.push(e,gone);for(const action of ['trash-row','trash-pick-mode','trash-pick','trash-pick-all','trash-pick-empty','trash-selected','trash-undo','restore-all','empty-trash','confirm-empty-trash'])await u.click('action',action,e.id);assert.equal(e.deletedAt,undefined);assert.ok(d.exams.includes(gone));assert.ok(gone.deletedAt);assert.equal(u.elements.get('#dialog').innerHTML,'');assert.doesNotMatch(u.elements.get('#app').innerHTML,/data-action="trash-row"|class="trash-bar"/);});
test('start resumes an approved stored session and loads the workspace without rendering the login form',async()=>{const h=sessionHarness({saved:{token:'d'.repeat(64)}});const p=demo();h.o.load=async()=>p;h.o.access=async()=>({meetings:[],requests:[]});h.context.location={hash:'',pathname:'/tool/',search:''};h.context.history={replaceState(){}};h.context.URLSearchParams=URLSearchParams;const result=await h.o.start();assert.equal(result.projectId,p.projectId);assert.ok(!h.els.get('#app').innerHTML.includes('login-form'));assert.equal(h.calls.length,1);});
