test('trash confirms permanent deletion, waits for central save and keeps failed deletions visible',async()=>{
 const u=await ui('admin'),d=u.sandbox.testUI.getDb(),e=C.newExam();C.trashExam({exams:[e],uses:[]},e.id);d.exams.push(e);
 await u.click('action','show-trash');assert.match(u.elements.get('#dialog').innerHTML,/Endgültig löschen/);
 await u.click('action','purge-exam',e.id);assert.match(u.elements.get('#dialog').innerHTML,/nicht wiederhergestellt/);assert.ok(d.exams.includes(e));
 await u.click('action','show-trash');assert.ok(d.exams.includes(e));
 u.online.save=async()=>{throw Error('Verbindung unterbrochen');};
 await u.click('action','confirm-purge-exam',e.id);assert.ok(u.sandbox.testUI.getDb().exams.some(x=>x.id===e.id));assert.match(u.elements.get('#toast').textContent,/Verbindung/);
 let finish;u.online.save=async candidate=>{assert.ok(!candidate.exams.some(x=>x.id===e.id));return new Promise(resolve=>finish=resolve);};
 const deleting=u.click('action','confirm-purge-exam',e.id);await new Promise(r=>setImmediate(r));
 assert.equal(u.elements.get('#app').inert,true);assert.equal(u.elements.get('#dialog').inert,true);assert.ok(u.sandbox.testUI.getDb().exams.some(x=>x.id===e.id));
 finish();await deleting;assert.ok(!u.sandbox.testUI.getDb().exams.some(x=>x.id===e.id));assert.equal(u.elements.get('#dialog').inert,false);assert.match(u.elements.get('#toast').textContent,/endgültig gelöscht/);
});
