test('successful deletion removes client baseline so a subsequent save does not recreate the draft',async()=>{
 const p=demo(),e=C.newExam();C.trashExam({exams:[e],uses:[]},e.id);p.exams.push(e);const calls=[];
 const context={HortiCore:C,HortiPrint:P,fetch:async(url,init)=>{if(url.endsWith('/api/project'))return Response.json({project:p,versions:{['exams:'+e.id]:7}});if(url.endsWith('/api/save')){const payload=JSON.parse(init.body);calls.push(payload);return Response.json({versions:{['exams:'+e.id]:0}});}throw Error('Unexpected request');}};
 vm.runInNewContext(client,context);const o=context.HortiOnline,loaded=await o.load();C.purgeExam(loaded,e.id);await o.save(loaded);await o.save(loaded);
 assert.equal(calls.length,1);assert.deepEqual(calls[0].changes,[{kind:'exams',id:e.id,version:7,value:null}]);
});

