function addOralFixture(d,{id='synthetic-oral',specialty='Baumschule',examType='AP',source=false}={}){
 const t={...structuredClone(d.tasks[0]),id,familyId:id+'-family',title:'SYNTHETIC_ORAL_'+id,text:'Synthetischen Sachverhalt erklären.',examType,specialty,kind:'oral',category:'Mündliche Aufgabe',tags:[],sourceIds:[],assetLinks:[],flags:[],criteria:[],points:37,minutes:17,solution:'SYNTHETIC_ORAL_SOLUTION',solutionStatus:'approved',reviewStatus:'approved',reviewedBy:'Test'};
 for(const key of ['planningCategories','planningCategoryCatalog','planningCategoryEvidence','practicalUnits','timing','pointsProposal','materials','sourceLayout'])delete t[key];
 if(source){const sourceId=id+'-source',text='1. Erklären Sie den synthetischen Sachverhalt.',block={id:id+'-block',text,originalText:text,x:40,y:100,width:420,height:30,fontSize:12,lineHeight:15,lines:[{text,runs:[{text,bold:false,italic:false}]}]};t.text=text;t.sourceIds=[sourceId];t.assetLinks=[{assetId:id+'-bg',audience:'candidate',role:'source-page'}];t.sourceLayout={version:1,sourceId,reference:'Synthetische mündliche Vorlage',sourcePdfHash:'a'.repeat(64),baselineText:text,warnings:[],pages:[{width:595,height:842,backgroundAssetId:id+'-bg',logos:[],blocks:[block]}]};d.sources.push({id:sourceId,name:'Synthetische mündliche Vorlage',specialty,examType,role:'Mündliche Aufgabe',text,attachmentIds:[]});d.assets.push({id:id+'-bg',name:'Synthetische Seite.png',mime:'image/png',data:'YWJj'});}
 d.families.push({id:t.familyId,title:t.title});d.tasks.push(t);return t;
}
function paperInput(u,item,field,index){const handlers={},attrs=new Map(),el={dataset:{paperItem:item.id,paperField:field,...(index===undefined?{}:{paperIndex:index})},isConnected:true,addEventListener:(name,fn)=>handlers[name]=fn,getAttribute:name=>name==='contenteditable'?'plaintext-only':attrs.get(name),setAttribute:(name,value)=>attrs.set(name,value),removeAttribute:name=>attrs.delete(name),closest:()=>null,dispatchEvent:ev=>handlers[ev.type]?.()};let content='';Object.defineProperties(el,{innerText:{get:()=>content,set:value=>content=String(value)},textContent:{get:()=>content,set:value=>content=String(value)}});const prior=u.sandbox.document.querySelectorAll;u.sandbox.document.querySelectorAll=q=>q==='[data-paper-field][contenteditable]'?[el]:prior(q);return {el,handlers,attrs};}

