function invitationClient({generation=4,expires=Date.now()+3600000,supplemented=false}={}){
 const h=sessionHarness({saved:{token:'e'.repeat(64)}}),code='apfel-birne-anker-besen-garten',access={meeting_id:'meeting',active:1,generation,expires};h.context.location={origin:'https://example.test',pathname:'/tool/'};const request=h.context.fetch;h.context.fetch=async(url,options)=>{if(url.endsWith('/api/session'))return request(url,options);h.calls.push({url,options});if(url.endsWith('/api/access'))return Response.json({meetings:[access],requests:[]});if(url.endsWith('/api/access/invitations'))return Response.json({generation:access.generation,expires:access.expires,supplemented,invitations:[{specialty:'Baumschule',token:code}]});throw Error('Unexpected invitation request');};return {...h,access,code};
}
test('fresh admin sessions retrieve the same active QR invitation without reopening access or persisting invitation text',async()=>{
 let first;for(let n=0;n<2;n++){const h=invitationClient();await h.o.restore();await h.o.access();assert.equal(h.o.link('meeting','Baumschule'),null);const result=await h.o.loadInvitations('meeting');assert.equal(result.generation,4);const link=h.o.link('meeting','Baumschule');assert.ok(link.endsWith('#invite='+h.code));if(n===0)first=link;else assert.equal(link,first);await h.o.loadInvitations('meeting');assert.equal(h.o.link('meeting','Baumschule'),first);assert.equal(h.calls.filter(x=>x.url.endsWith('/api/access/invitations')).length,2);for(const call of h.calls.filter(x=>x.url.endsWith('/api/access/invitations'))){assert.equal(call.options.method,'POST');assert.deepEqual(JSON.parse(call.options.body),{meetingId:'meeting'});assert.equal(call.options.headers.Authorization,'Bearer '+'e'.repeat(64));}assert.ok(!h.calls.some(x=>x.url.endsWith('/open')));assert.ok(![...h.values.values()].some(x=>x.includes(h.code)));}
});
test('invitation caches are discarded after closure, generation change, expiry and failed retrieval',async()=>{
 for(const reason of ['closed','generation','expired','access-error','invitation-error']){const h=invitationClient();await h.o.restore();await h.o.access();await h.o.loadInvitations('meeting');if(reason==='closed')h.access.active=0;if(reason==='generation')h.access.generation++;if(reason==='expired')h.access.expires=Date.now()-1;if(reason.endsWith('error')){const fetch=h.context.fetch;h.context.fetch=(url,options)=>url.endsWith(reason==='access-error'?'/api/access':'/api/access/invitations')?Promise.reject(Error('Network unavailable')):fetch(url,options);await assert.rejects(reason==='access-error'?h.o.access():h.o.loadInvitations('meeting'),/Network/);}else await h.o.access();assert.equal(h.o.link('meeting','Baumschule'),null,reason);assert.equal(h.o.invitations.has('meeting'),false,reason);assert.equal(h.o.invitationWindows.has('meeting'),false,reason);}
});
