 const e=C.newExam({specialty:'Baumschule',examType:'AP',examYear:2027,workshopId:'meeting',pattern:L.snapshotPattern(d,L.pattern(d,'AP','Baumschule'))});C.addItem(e,t);e.workflowStep=2;
